// KINEO-ROTEIRO-CURTO-SEM-FALHA-2026-10-22 — local whole-suite runner; no production access.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const [root,label,onlyList]=process.argv.slice(2),outDir=process.env.KINEO_QA_OUTPUT_DIR||path.join(require('node:os').tmpdir(),'kineo-roteiro-curto-2210-validation'),preload=path.join(__dirname,'offline-preload.cjs');
if(!root||!label)throw new Error('Usage: node run-suite.cjs root label [list.json]');
const scripts=fs.readdirSync(path.join(root,'scripts')).filter(x=>/^test-.*\.mjs$/.test(x)).sort().map(x=>'scripts/'+x);
const tests=fs.existsSync(path.join(root,'tests'))?fs.readdirSync(path.join(root,'tests')).filter(x=>/\.test\.mjs$/.test(x)).sort().map(x=>'tests/'+x):[];
const proves=fs.readdirSync(path.join(root,'scripts')).filter(x=>/^prove-.*\.mjs$/.test(x)).sort().map(x=>'scripts/'+x);
const list=onlyList?JSON.parse(fs.readFileSync(onlyList,'utf8')):[...scripts,...tests,...proves];
const serial=[],parallel=[];for(const p of list){const src=fs.readFileSync(path.join(root,p),'utf8');(/\b(?:writeFileSync|writeFile|unlinkSync|rmSync|appendFileSync)\s*\(/.test(src)?serial:parallel).push(p);}
const env={}; for(const k of ['PATH','Path','SystemRoot','SYSTEMROOT','WINDIR','TEMP','TMP','COMSPEC','PATHEXT','APPDATA','LOCALAPPDATA','USERPROFILE','HOMEDRIVE','HOMEPATH','NUMBER_OF_PROCESSORS'])if(process.env[k])env[k]=process.env[k];
env.GIT_ALLOW_PROTOCOL='file';env.GIT_TERMINAL_PROMPT='0';env.GIT_CONFIG_COUNT='1';env.GIT_CONFIG_KEY_0='core.autocrlf';env.GIT_CONFIG_VALUE_0='true';
env.NODE_OPTIONS='--require='+JSON.stringify(preload);env.NO_COLOR='1';env.FORCE_COLOR='0';
const dest=path.join(outDir,label);fs.mkdirSync(dest,{recursive:true});const previous=fs.existsSync(path.join(outDir,label+'.json'))?JSON.parse(fs.readFileSync(path.join(outDir,label+'.json'),'utf8')):null;const results=previous?.results??[];let active=0,done=results.length;const started=previous?Date.parse(previous.started):Date.now();const doneFiles=new Set(results.map(r=>r.file));
function normalize(text){return text.replace(/\x1b\[[0-9;]*m/g,'').replace(/\r\n/g,'\n');}
function failureLines(text){return normalize(text).split('\n').filter(l=>/^\s*(?:[✗✘×❌]|FAIL\b|not ok\b|AssertionError\b|Error\b|FALH|\[FAIL\]|x )/i.test(l)||/KINEO_OFFLINE_BLOCKED/.test(l)).map(l=>l.trim());}
function save(){fs.writeFileSync(path.join(outDir,label+'.json'),JSON.stringify({label,root,base:cp.execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),started:new Date(started).toISOString(),finished:new Date().toISOString(),total:list.length,parallel:parallel.length,serial:serial.length,done,pass:results.filter(r=>r.status===0).length,fail:results.filter(r=>r.status!==0).length,results:results.slice().sort((a,b)=>a.file.localeCompare(b.file))},null,2));}
async function run(file){const t=Date.now();return new Promise(resolve=>{let output='',timedOut=false;const proc=cp.spawn(process.execPath,['--require',preload,file],{cwd:root,env,windowsHide:true,stdio:['ignore','pipe','pipe']});for(const stream of [proc.stdout,proc.stderr])stream.on('data',b=>{output+=b.toString();if(output.length>16*1024*1024)proc.kill();});const timer=setTimeout(()=>{timedOut=true;proc.kill();},Number(process.argv[6]||120000));proc.on('error',e=>{output+='\nError '+e.message;});proc.on('close',(status,signal)=>{clearTimeout(timer);const log=file.replace(/[\\/]/g,'__')+'.log';fs.writeFileSync(path.join(dest,log),output);results.push({file,status,signal,timedOut,ms:Date.now()-t,log,failures:failureLines(output)});done++;if(done%25===0||timedOut){save();console.log(`${label} ${done}/${list.length}; pass=${results.filter(r=>r.status===0).length}, fail=${results.filter(r=>r.status!==0).length}; ${(Date.now()-started)/1000}s`);}resolve();});});}
(async()=>{const pending=parallel.filter(p=>!doneFiles.has(p));let next=0;await Promise.all(Array.from({length:Number(process.argv[5]||8)},async()=>{while(next<pending.length){const file=pending[next++];await run(file);}}));for(const file of serial)if(!doneFiles.has(file))await run(file);save();console.log(label+' COMPLETE '+done+'; pass='+results.filter(r=>r.status===0).length+'; fail='+results.filter(r=>r.status!==0).length);})().catch(e=>{save();console.error(e);process.exit(1);});

// KINEO-ROTEIRO-CURTO-SEM-FALHA-2026-10-22 — local validation isolation only.
const fs = require('node:fs');
const path = require('node:path');
const {syncBuiltinESMExports} = require('node:module');
const blocked = kind => { throw new Error('KINEO_OFFLINE_BLOCKED: ' + kind); };
const isEnv = p => typeof p !== 'number' && /(^|[\\/])\.env(?:[.\\/]|$)/i.test(String(p instanceof URL ? p.pathname : p));
for (const name of ['readFileSync','readFile','openSync','open','createReadStream']) {
  const original=fs[name]; fs[name]=function(p,...args){ if(isEnv(p)) return blocked('env read'); return original.call(this,p,...args); };
}
const exists=fs.existsSync; fs.existsSync=function(p){ return isEnv(p) ? false : exists.call(this,p); };
const untouchable=p=>/(?:^|[\\/])lib[\\/](?:engineWall|homeVideoCuration)\.ts$/i.test(String(p instanceof URL?p.pathname:p));
for(const name of ['writeFileSync','writeFile','appendFileSync','appendFile','unlinkSync','unlink','rmSync','rm','renameSync','rename','copyFileSync','copyFile']){const original=fs[name];fs[name]=function(p,...args){if(untouchable(p)||(/rename|copyFile/.test(name)&&untouchable(args[0])))return blocked('protected source write');return original.call(this,p,...args);};}
for(const name of ['readFile','open']){ const original=fs.promises[name]; fs.promises[name]=function(p,...args){ if(isEnv(p)) return Promise.reject(new Error('KINEO_OFFLINE_BLOCKED: env read')); return original.call(this,p,...args); }; }
for(const [mod,names] of [['node:http',['request','get']],['node:https',['request','get']],['node:net',['connect','createConnection']],['node:tls',['connect']],['node:dns',['lookup','resolve','resolve4','resolve6']]]) {
  const m=require(mod); for(const name of names) m[name]=()=>blocked('network ' + mod + '.' + name);
}
require('node:net').Socket.prototype.connect=function(){return blocked('network socket');};
globalThis.fetch=async()=>blocked('network fetch');
const cp=require('node:child_process');
function allowed(file,args){
 const base=path.basename(String(file)).toLowerCase();
 if(base==='git'||base==='git.exe'){
   const a=Array.isArray(args)?args:[]; let i=0; if(a[0]==='-C')i=2;
   return ['show','log','diff','status','rev-parse','merge-base','ls-files','cat-file','diff-tree','hash-object'].includes(a[i]);
 }
 return ['node','node.exe','ffprobe','ffprobe.exe'].includes(base);
}
for(const name of ['execFile','execFileSync','spawn','spawnSync']){ const original=cp[name]; cp[name]=function(file,args,...rest){if(!allowed(file,args)) return blocked('child command ' + path.basename(String(file)));return original.call(this,file,args,...rest);};}
for(const name of ['exec','execSync']){ const original=cp[name];cp[name]=function(command,...args){ if(!/^git\s+(?:show|log|diff|status|rev-parse|merge-base|ls-files|cat-file|diff-tree|hash-object)\b/.test(String(command))||/[;&|`\r\n]/.test(String(command)))return blocked('shell command'); return original.call(this,command,...args);};}
syncBuiltinESMExports();

const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const [rootArg,label]=process.argv.slice(2),outDir=__dirname;
if(!rootArg||!label)throw new Error('Usage: node run-tsc.cjs root label');
const root=path.resolve(rootArg);
const env={};for(const k of ['PATH','Path','SystemRoot','SYSTEMROOT','WINDIR','TEMP','TMP','COMSPEC','PATHEXT','APPDATA','LOCALAPPDATA','USERPROFILE','HOMEDRIVE','HOMEPATH','NUMBER_OF_PROCESSORS'])if(process.env[k])env[k]=process.env[k];
env.NODE_OPTIONS='--require='+JSON.stringify(path.join(__dirname,'offline-preload.cjs'));env.NO_COLOR='1';env.FORCE_COLOR='0';
const start=Date.now(),args=[path.join(root,'node_modules/typescript/bin/tsc'),'--noEmit','--incremental','false'];
const result=cp.spawnSync(process.execPath,args,{cwd:root,env,windowsHide:true,encoding:'utf8',timeout:600000,maxBuffer:16*1024*1024});
fs.writeFileSync(path.join(outDir,label+'-tsc.log'),(result.stdout||'')+(result.stderr||'')+(result.error?'\n'+String(result.error):''));
const receipt={label,root,base:cp.execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),command:'tsc --noEmit --incremental false',status:result.status,signal:result.signal,error:result.error?String(result.error):null,ms:Date.now()-start,date:new Date().toISOString()};
fs.writeFileSync(path.join(outDir,label+'-tsc.json'),JSON.stringify(receipt,null,2));console.log(JSON.stringify(receipt));
process.exitCode=result.status===0?0:1;
